function fresh(){
 const tasks=[],rooms=[...new Set(SEED_DATA.tasks.map(t=>t.room))].sort();
 const perRoom={};SEED_DATA.tasks.forEach(t=>(perRoom[t.room]??=[]).push(t));
 // Controlled, low-density first setup: two room packages per day, tasks in each room staggered.
 rooms.forEach((room,ri)=>{(perRoom[room]||[]).forEach((t,ti)=>{let offset=Math.floor(ti/2)*13+Math.floor(ri/2);if(/fenster/i.test(t.text))offset=Math.min(offset,14+Math.floor(ti/2));tasks.push({id:'seed-'+tasks.length,text:t.text.trim(),room,area:t.area||'Raum',interval:Number(t.interval)||30,due:addDays(today(),offset),planned:addDays(today(),offset),active:true,source:t.source||'seed',history:[]})})});
 SEED_DATA.dailyTasks.forEach((t,i)=>tasks.push({id:'daily-'+i,text:t.text.trim(),room:'Alltag',interval:0,due:today(),planned:today(),active:true,daily:true,group:t.group,source:'daily',history:[]}));
 return {schema:1,tasks,rooms:[...new Set(tasks.map(t=>t.room))],completedDays:{},migrated:false,createdAt:new Date().toISOString()}
}
function load(){try{let x=JSON.parse(localStorage.getItem(KEY));if(x&&Array.isArray(x.tasks))return normalize(x)}catch{}return fresh()}
function normalize(s){s.tasks=(s.tasks||[]).map((t,i)=>{let planned=t.planned||t.plannedDate||t.date||t.due||t.start||today();return {...t,id:String(t.id||t.key||'task-'+i),text:String(t.text||t.name||'Aufgabe ohne Titel'),room:String(t.room||'Ohne Raum'),interval:Math.max(0,Number(t.interval||t.repeat||0)||0),due:t.due||t.dueDate||planned,planned,active:t.active!==false,history:Array.isArray(t.history)?t.history:[]}});for(const t of s.tasks){if(t.active&&(!t.planned||!/^\d{4}-\d{2}-\d{2}$/.test(t.planned)))t.planned=t.due||today();if(!t.due)t.due=t.planned||today()}s.rooms=[...new Set([...s.tasks.map(t=>t.room),...(s.rooms||[])])];s.completedDays=s.completedDays||{};return s}
let state=load(),view='today',calDate=today(),notice='';function save(){state=normalize(state);localStorage.setItem(KEY,JSON.stringify(state))}function byDate(){return state.tasks.filter(t=>t.active&&!t.daily&&t.planned===today()).sort((a,b)=>a.room.localeCompare(b.room)||a.text.localeCompare(b.text))}function daily(){return state.tasks.filter(t=>t.active&&t.daily)}function doneToday(t){return !!t.doneOn&&t.doneOn===today()}
function render(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const root=$('#app');if(view==='today')root.innerHTML=renderToday();else if(view==='catalog')root.innerHTML=renderCatalog();else if(view==='calendar')root.innerHTML=renderCalendar();else root.innerHTML=renderMigration();bind()}
function renderToday(){let ds=daily(),due=byDate(),done=state.tasks.filter(t=>t.active&&t.doneOn===today()).length;return `<div class="card"><div class="row between"><div><h2>Heute</h2><div class="muted">${new Date().toLocaleDateString('de-AT',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div></div><span class="pill">${done} erledigt</span></div><div class="ok">Jede aktive Aufgabe hat einen konkreten Termin. Sichtbar ist ausschließlich „Termin“; Fälligkeit und Intervall bleiben intern getrennt.</div></div><div class="two"><section class="card"><h3>Deine täglichen Routinen</h3>${ds.length?ds.map(taskRow).join(''):'<div class="empty">Keine Routinen.</div>'}</section><section class="card"><h3>Heute eingeplant</h3>${due.length?groupedRows(due):'<div class="empty">Für heute sind keine zusätzlichen Raumaufgaben eingeplant.</div>'}</section></div>`}
function taskRow(t){return `<div class="task"><input type="checkbox" data-done="${esc(t.id)}" ${doneToday(t)?'checked':''} aria-label="Erledigt"><div><div class="task-title">${esc(t.text)}</div><div class="muted">${esc(t.room)} · <span class="date">Termin: ${fmt(t.planned)}</span></div></div><button class="btn" data-edit="${esc(t.id)}">Bearbeiten</button></div>`}
function groupedRows(ts){let rooms={};ts.forEach(t=>(rooms[t.room]??=[]).push(t));return Object.entries(rooms).map(([r,items])=>`<div style="margin-top:12px"><h3>${esc(r)}</h3>${items.map(taskRow).join('')}</div>`).join('')}
function renderCatalog(){let rooms=[...new Set(state.tasks.filter(t=>t.active).map(t=>t.room))].sort(),filter=window.roomFilter||'';let ts=state.tasks.filter(t=>t.active&&(!filter||t.room===filter)).sort((a,b)=>a.planned.localeCompare(b.planned)||a.room.localeCompare(b.room));return `<div class="card"><div class="row between"><div><h2>Aufgabenkatalog</h2><div class="muted">Sortiert nach Termin. Aktive Aufgaben ohne Termin werden vor dem Speichern automatisch repariert.</div></div><button class="btn primary" id="addTask">+ Aufgabe</button></div><div class="fields"><div><label>Raum filtern</label><select id="roomFilter"><option value="">Alle Räume</option>${rooms.map(r=>`<option ${filter===r?'selected':''}>${esc(r)}</option>`).join('')}</select></div><div><label>Aufgabe suchen</label><input id="searchTask" placeholder="Begriff eingeben"></div></div><div id="taskList">${ts.map(taskRow).join('')}</div></div>`}
function renderCalendar(){let month=calDate.slice(0,7),days=Array.from({length:new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate()},(_,i)=>`${month}-${String(i+1).padStart(2,'0')}`);return `<div class="card"><div class="row between"><div><h2>Kalender</h2><div class="muted">Alle Ansichten lesen dieselben gespeicherten Termine.</div></div><input type="month" id="month" value="${month}" style="max-width:180px"></div>${days.map(d=>{let ts=state.tasks.filter(t=>t.active&&t.planned===d);return `<div class="task" style="grid-template-columns:95px 1fr"><strong>${fmt(d)}</strong><div>${ts.length?ts.map(t=>`<div style="padding:3px 0">${esc(t.text)} <span class="tag">${esc(t.room)}</span></div>`).join(''):'<span class="muted">Keine Aufgaben</span>'}</div></div>`}).join('')}</div>`}
function renderMigration(){let legacy=findLegacy(),summary=legacy?legacySummary(legacy.data):null;return `<div class="card"><h2>Kontrollierte Datenübernahme</h2><p class="muted">Die alte App bleibt unverändert. 2.0 verwendet den eigenen Speicherbereich <code>${KEY}</code>. Eine automatische Übernahme erfolgt nur nach Vorschau und Bestätigung.</p>${notice?`<div class="ok">${esc(notice)}</div>`:''}${state.migrated?'<div class="ok">Eine Datenübernahme wurde bereits durchgeführt. Du kannst jederzeit eine neue JSON-Sicherung importieren.</div>':''}${summary?`<div class="warn"><strong>Alte Daten im selben Browser gefunden.</strong><br>${summary.tasks} Aufgaben-/Änderungsdaten · ${summary.rooms} erkennbare Räume · ${summary.history} gespeicherte Verlaufs-/Erledigungsbereiche.<br>Die alte App wird dabei nur gelesen.</div><button class="btn primary" id="migrateLocal">Vorschau übernehmen und in 2.0 importieren</button>`:'<div class="muted">Keine alte App-Datenstruktur im aktuellen Browser-Speicher gefunden. Du kannst eine JSON-Sicherung importieren.</div>'}<hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h3>Sicherung importieren</h3><p class="muted">Wähle eine JSON-Datei aus einem Backup. ZIP-Dateien können hier nicht direkt eingelesen werden.</p><input id="importFile" type="file" accept="application/json,.json"><div class="row" style="margin-top:12px"><button class="btn" id="export">2.0-Daten exportieren</button><button class="btn" id="backup">2.0-Sicherung herunterladen</button><button class="btn danger" id="reset">2.0-Daten zurücksetzen</button></div><div class="muted" style="margin-top:12px">Vorhandene Aufgaben werden anhand stabiler Schlüssel soweit möglich zusammengeführt. Termin, Intervall, Erledigungshistorie und eigene Änderungen werden getrennt behandelt; unklare Daten werden nicht in die alte App zurückgeschrieben.</div></div>`}
function findLegacy(){for(const k of LEGACY_KEYS){try{let d=JSON.parse(localStorage.getItem(k)||'null');if(d&&typeof d==='object')return {key:k,data:d}}catch{}}return null}
function legacySummary(d){let tasks=0;for(const k of ['custom','todayExtras','catalogEdits','catalogDates','manualDates']){let v=d[k];if(Array.isArray(v))tasks+=v.length;else if(v&&typeof v==='object')tasks+=Object.keys(v).length}let rooms=new Set();(d.custom||[]).forEach(t=>t.room&&rooms.add(t.room));Object.values(d.catalogEdits||{}).forEach(t=>t?.room&&rooms.add(t.room));return {tasks,rooms:rooms.size,history:Object.keys(d.completionHistory||{}).length+Object.keys(d.done||{}).length}}
function importLegacy(raw){let source=raw.data||raw;let out=state.tasks.slice();let map=new Map(out.map(t=>[t.id,t]));const upsert=(id,patch)=>{let old=map.get(id);if(old)Object.assign(old,patch);else{let t={id,text:'Aufgabe',room:'Ohne Raum',interval:0,planned:today(),due:today(),active:true,history:[]};Object.assign(t,patch,{id});map.set(id,t)}};
// Preserve user-created tasks and user edits from legacy state. Seed catalog is not inferred from partial data.
(source.custom||[]).forEach((c,i)=>{if(!c||!c.text)return;let id=String(c.key||`legacy-custom-${c.id||i}`),p=c.start||c.date||today();upsert(id,{text:c.text,room:c.room||'Ohne Raum',interval:Number(c.interval||c.repeat||0)||0,planned:p,due:p,active:true,source:'legacy-custom',history:[]})});
function matchLegacyKey(k,e){let parts=String(k).split('|');let room=e?.room|| (parts.length>=3?parts[1]:'');let oldText=parts.length>=3?parts.slice(2).join('|'):'';return [...map.values()].find(t=>room&&t.room===room&&(t.text===oldText||t.text===e?.text))}
for(const [k,e] of Object.entries(source.catalogEdits||{})){if(!e||!e.text)continue;let existing=map.get(k)||matchLegacyKey(k,e),p=source.manualDates?.[k]||source.catalogDates?.[k]||e.start||existing?.planned||today();if(existing){Object.assign(existing,{text:e.text,room:e.room||existing.room,interval:Number(e.interval??existing.interval??0)||0,planned:p,due:existing.due||p,active:source.catalogDeleted?.[k]!==true,source:'legacy-edit'})}else upsert(k,{text:e.text,room:e.room||'Ohne Raum',interval:Number(e.interval||0)||0,planned:p,due:p,active:source.catalogDeleted?.[k]!==true,source:'legacy-edit'})}
for(const [k,p] of Object.entries({...source.catalogDates,...source.manualDates})){if(!p)continue;let t=map.get(k)||matchLegacyKey(k,source.catalogEdits?.[k]);if(t){t.planned=p;t.due=t.due||p}}
for(const t of map.values()){let key=t.id;let hist=source.completionHistory?.[key]||source.completionHistory?.[t.text];if(Array.isArray(hist))t.history=[...new Set([...t.history,...hist.map(x=>typeof x==='string'?x:x?.date).filter(Boolean)])].sort().reverse().slice(0,20);let last=source.lastDone?.[key]||source.done?.[key];if(typeof last==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(last))t.lastDone=last}
state.tasks=[...map.values()];state.rooms=[...new Set([...state.tasks.map(t=>t.room),...(source.rooms||[])])];state.migrated=true;state.migrationInfo={source:'legacy',importedAt:new Date().toISOString(),legacyKey:raw.key||'JSON-Import'};save();notice=`Import abgeschlossen: ${state.tasks.length} Aufgaben in 2.0 gespeichert. Die alte App blieb unverändert.`;}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelectorAll('[data-done]').forEach(c=>c.onchange=()=>{let t=state.tasks.find(t=>t.id===c.dataset.done);if(!t)return;if(c.checked){t.doneOn=today();t.history=[today(),...(t.history||[])].filter((x,i,a)=>a.indexOf(x)===i).slice(0,20);if(!t.daily){let next=addDays(today(),Math.max(1,t.interval||7));t.due=next;t.planned=next}}else{t.doneOn='';if(!t.daily){t.planned=t.due||today()}}save();render()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editTask(b.dataset.edit));$('#addTask')?.addEventListener('click',()=>editTask(''));$('#roomFilter')?.addEventListener('change',e=>{window.roomFilter=e.target.value;render()});$('#searchTask')?.addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('#taskList .task').forEach(el=>el.classList.toggle('hidden',!el.innerText.toLowerCase().includes(q)))});$('#month')?.addEventListener('change',e=>{calDate=e.target.value+'-01';render()});$('#migrateLocal')?.addEventListener('click',()=>{let l=findLegacy();if(l&&confirm('Die gefundenen alten Daten jetzt in den separaten 2.0-Speicher übernehmen? Die alte App wird nicht verändert.')){importLegacy(l);render()}});$('#importFile')?.addEventListener('change',async e=>{let f=e.target.files?.[0];if(!f)return;try{let d=JSON.parse(await f.text());if(!confirm('Diese JSON-Daten in 2.0 übernehmen? Bestehende 2.0-Aufgaben werden soweit möglich zusammengeführt.'))return;importLegacy({data:d,key:f.name});render()}catch{alert('Die Datei ist keine gültige JSON-Sicherung.')}});$('#export')?.addEventListener('click',()=>download());$('#backup')?.addEventListener('click',()=>download());$('#reset')?.addEventListener('click',()=>{if(confirm('Nur den separaten 2.0-Speicher zurücksetzen? Die alte App bleibt unverändert.')){localStorage.removeItem(KEY);state=fresh();save();notice='2.0 wurde zurückgesetzt.';render()}})}
function editTask(id){let t=state.tasks.find(x=>x.id===id),isNew=!t;if(!t)t={id:'task-'+Date.now(),text:'',room:'',interval:7,planned:today(),due:today(),active:true,history:[]};const roomOptions=[...new Set([...state.tasks.map(x=>x.room),t.room].filter(Boolean))].map(r=>`<option ${r===t.room?'selected':''}>${esc(r)}</option>`).join('');let box=document.createElement('div');box.style.cssText='position:fixed;inset:0;background:#17191266;display:grid;place-items:center;padding:18px;z-index:9';box.innerHTML=`<form class="card" style="width:min(520px,100%);max-height:90vh;overflow:auto"><div class="row between"><h2>${isNew?'Neue Aufgabe':'Aufgabe bearbeiten'}</h2><button type="button" class="btn" id="close">Schließen</button></div><div class="fields"><div style="grid-column:1/-1"><label>Aufgabe</label><input name="text" required value="${esc(t.text)}"></div><div><label>Raum</label><input name="room" list="rooms" required value="${esc(t.room)}"><datalist id="rooms">${roomOptions}</datalist></div><div><label>Termin</label><input name="planned" type="date" required value="${esc(t.planned||today())}"></div><div><label>Intervall in Tagen (0 = kein automatisches Intervall)</label><input name="interval" type="number" min="0" step="1" value="${Number(t.interval)||0}"></div></div><div class="row"><button class="btn primary" type="submit">Speichern</button>${!isNew?'<button class="btn danger" type="button" id="deactivate">Deaktivieren</button>':''}</div></form>`;document.body.append(box);box.querySelector('#close').onclick=()=>box.remove();box.querySelector('form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),p=String(f.get('planned')||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(p)){alert('Bitte einen konkreten Termin wählen.');return}let updated={...t,text:String(f.get('text')).trim(),room:String(f.get('room')).trim(),planned:p,due:t.due||p,interval:Math.max(0,Number(f.get('interval'))||0),active:true};if(!updated.text||!updated.room)return;if(isNew)state.tasks.push(updated);else Object.assign(t,updated);save();box.remove();render()};box.querySelector('#deactivate')?.addEventListener('click',()=>{if(confirm('Aufgabe aus dem aktiven Katalog entfernen? Verlauf bleibt erhalten.')){t.active=false;save();box.remove();render()}})}
function download(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Unser-Zuhause-2.0-Sicherung-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
